<script setup>
import { ref } from 'vue';
import { api } from '../../services/api.js';
import { auth } from '../../services/auth.js';
import { notify,confirmDialog } from '../../services/notifications.js';
import { useCollection,shortDate,money } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
const overdueOnly=ref(false);
const {rows,loading,error,meta,load,updateQuery}=useCollection('/admin/users',()=>overdueOnly.value?{billingStatus:'grace_expired'}:{});
const columns=[{key:'name',label:'Vendedor'},{key:'planId',label:'Plan'},{key:'subscription',label:'Suscripción'},{key:'planExpiresAt',label:'Vencimiento'},{key:'active',label:'Estado'}];
async function remove(row){if(!await confirmDialog({title:'Desactivar vendedor',message:`${row.name||row.email} dejará de acceder a su cuenta y sus tiendas. Sus registros se conservarán.`,confirmText:'Desactivar',danger:true}))return;try{await api.delete(`/admin/users/${row._id}`);notify.success('Vendedor desactivado.');load()}catch(e){notify.error(e.message)}}
async function impersonate(row){if(!await confirmDialog({title:'Entrar como vendedor',message:`Vas a abrir el panel personificado como ${row.name||row.email}. Esta herramienta sólo funciona en desarrollo/prueba.`,confirmText:'Entrar como vendedor'}))return;try{await api.post(`/admin/users/${row._id}/impersonate`,{});window.location.assign('/app/dashboard')}catch(e){notify.error(e.message)}}
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">PERSONAS QUE EMPRENDEN</p><h1>Usuarios</h1><p>Administrá vendedores, sus planes y las oportunidades de cada negocio.</p></div><div class="p-page-header-actions"><button class="btn" :class="overdueOnly?'btn-primary':'btn-secondary'" @click="overdueOnly=!overdueOnly"><Icon name="receipt" :size="15"/>{{overdueOnly?'Mostrando fuera de gracia':'Ver fuera de gracia'}}</button><RouterLink to="/app/users/new" class="btn btn-primary"><Icon name="plus" :size="16"/>Nuevo vendedor</RouterLink></div></header><div v-if="error" class="p-error">{{error}} <button class="btn btn-text" @click="load">Reintentar</button></div><DataTable :rows="rows" :columns="columns" :loading="loading" server :total="meta.total" :page="meta.page" :limit="meta.limit" @query-change="updateQuery" search-placeholder="Buscar por nombre o email..."><template #cell-name="{row}"><div class="p-product-cell"><span class="p-avatar">{{(row.name||row.email).slice(0,2).toUpperCase()}}</span><span><strong>{{row.name||'Sin nombre'}}</strong><small>{{row.email||row.username}}</small></span></div></template><template #cell-planId="{row}">{{row.planId?.name||row.plan?.name||(row.planId?'Plan asignado':row.trialEndsAt&&new Date(row.trialEndsAt)>new Date()?'Prueba gratuita':'Sin plan')}}</template><template #cell-subscription="{row}"><span v-if="row.subscription?.graceExpired" class="p-badge red">Fuera de gracia</span><span v-else-if="row.subscription?.inGrace" class="p-badge orange">En cortesía</span><span v-else-if="row.subscription?.automatic" class="p-badge green">Automática</span><span v-else class="p-badge">Sin débito automático</span><small v-if="row.subscription?.periodsDue">{{row.subscription.periodsDue}} {{row.subscription.periodsDue===1?'período':'períodos'}} · {{money(row.subscription.debtAmount)}}</small></template><template #cell-planExpiresAt="{row}">{{shortDate(row.planExpiresAt||row.trialEndsAt)}}</template><template #cell-active="{row}"><span class="p-badge dot" :class="row.active?'green':'red'">{{row.role==='admin'?'Administrador':row.active?'Activo':'Desactivado'}}</span></template><template #actions="{row}"><button v-if="auth.features.devImpersonation&&row.active" class="btn btn-secondary btn-small" title="Entrar personificado en modo prueba" @click="impersonate(row)"><Icon name="users" :size="13"/>Entrar como vendedor</button><RouterLink v-if="row.role!=='admin'" :to="`/app/users/${row._id}`" class="btn btn-secondary btn-small"><Icon name="edit" :size="13"/>Gestionar</RouterLink><button v-if="row.role!=='admin'&&row.active" class="p-icon-btn danger" title="Desactivar vendedor" @click="remove(row)"><Icon name="trash" :size="14"/></button></template></DataTable></div></template>
